const $=id=>document.getElementById(id),stage=$('stage'),canvas=$('world');
const music=new ForestMusic();
const defaults={volume:.65,offset:0,quality:true,reduced:matchMedia('(prefers-reduced-motion: reduce)').matches};
let settings={...defaults},records={};try{settings={...defaults,...JSON.parse(localStorage.getItem('pinebeat-settings')||'{}')};records=JSON.parse(localStorage.getItem('pinebeat-records')||'{}');}catch{}
